# -*- coding: utf-8 -*-
# patch_iskra_knowledge.py
# ============================================================
# ПАТЧ: синхронизация книжки Искры с движком (аудит фундамента).
# Спринт 45 · 2026-06-16
#
# WILLIAMS_MATH.md обновлён — НЕ меняя движок, синхронизируем знание:
#   · раздел 5b: divergent_bar / BuDB Котина (был на входе, не в книжке)
#   · случай 5: флаг divergence_ao смотрит ТОЛЬКО два последних пивота —
#     голос Искры может рассуждать шире, но сигнал = флаг движка
#   · раздел 9: граница органов — Аллигатор и АНГУЛЯЦИЯ это Морж, не Искра.
#     Искра объявляет Точку Ноль по энергии, Морж проверяет структурой.
#   · раздел 8: Аллигатор убран из входа Искры (он не её орган)
#
# Математика (AO/AC/Аллигатор/фракталы/дивергенция) сверена с
# williams_core.py — совпадает. Движок НЕ трогается.
#
# Бэкап (.bak). Запуск из корня репо:  python patch_iskra_knowledge.py
# ============================================================
import base64, os, shutil
FILES = {
    "studio/modules/trading/A01/forge/knowledge/WILLIAMS_MATH.md": ""
}
def main():
    root = os.getcwd()
    print("=== ПАТЧ: книжка Искры синхронизирована с движком ===")
    for dest, b64 in FILES.items():
        path = os.path.join(root, dest.replace("/", os.sep))
        os.makedirs(os.path.dirname(path), exist_ok=True)
        if os.path.exists(path):
            shutil.copy2(path, path + ".bak")
            print(f"  [BAK] {dest}.bak")
        open(path, "wb").write(base64.b64decode(b64))
        print(f"  [OK ] {dest}")
    print("=== ГОТОВО ===")
    print("Искра теперь читает книжку, согласованную с реальным ядром.")
    print("Аллигатор/ангуляция явно отданы Моржу — шов чистый.")
    print("Можно будить Моржа (A02).")
if __name__ == "__main__":
    main()
